#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ask_id KEY "Prompt" REGEX keeps asking until the value matches, so a stray
# space or the wrong ID type is caught here, not in the Lambda.
ask_id() {
  local key="$1" prompt="$2" pattern="$3" value
  while true; do
    ask "$key" "$prompt" || return 1
    value="${!key}"
    value="$(printf '%s' "$value" | tr -d '[:space:]')"
    if [[ "$value" =~ $pattern ]]; then
      printf -v "$key" '%s' "$value"
      return 0
    fi
    warn "That doesn't look right. Copy the whole ID and try again."
  done
}

run_wizard() {

TOTAL_STAGES=10
EPISODE="${1:-}"
REPO_ROOT="/c/code/v1be-infra"
REGION="ap-southeast-1"
AUDIENCE="https://api.anthropic.com"
export AWS_PROFILE="v1be-admin"
MEMBER_PROFILE="v1be-admin-portfolio"
# Stops Git Bash rewriting the SSM name, which starts with /, into a Windows path.
export MSYS_NO_PATHCONV=1
CONSOLE="https://platform.claude.com"

# Admin logins happen only in Windows Sandbox (ADR-0012).
if [[ ! -d "$REPO_ROOT/sandbox" ]]; then
  warn "Stopping: this isn't Windows Sandbox. Open v1be-admin.wsb and run it there."
  exit 1
fi

if [[ ! "$EPISODE" =~ ^[a-z0-9-]+$ ]]; then
  warn "Usage: anthropic-workload.sh <episode>, such as anthropic-workload.sh portfolio-site"
  exit 1
fi
if ! grep -qE "^[[:space:]]*${EPISODE}[[:space:]]*=.*anthropic[[:space:]]*=[[:space:]]*true" "$REPO_ROOT/stacks/episodes.tfvars"; then
  warn "Stopping: $EPISODE isn't in stacks/episodes.tfvars with anthropic = true."
  exit 1
fi

ROLE_NAME="v1be-$EPISODE-api-production"
PARAM="/$EPISODE/third-party/anthropic-federation"

banner "Anthropic: connect $EPISODE's Lambda, with no key"

stage "Before you start"
say "This gives $EPISODE its own Anthropic workspace with a spend limit, and lets"
say "its production Lambda reach Claude with a short-lived AWS token instead of a key."
note "Nothing secret is copied. The four IDs you copy are only names, and they go to SSM at"
note "$PARAM, never into a repo or a chat."
note "Needs: the accounts stack applied in portfolio (v1be-infra #39), and an"
note "admin or owner login in the Claude Console."
pause

stage "Sign in as v1be-admin"
if ! aws configure get sso_session --profile "$AWS_PROFILE" >/dev/null 2>&1 \
  && ! aws configure get sso_start_url --profile "$AWS_PROFILE" >/dev/null 2>&1; then
  warn "Stopping: this Sandbox has no $AWS_PROFILE profile. Run identity-center.sh, then come back."
  exit 1
fi
if aws sts get-caller-identity --profile "$AWS_PROFILE" >/dev/null 2>&1; then
  say "Already signed in to AWS."
else
  step "A browser opens. Sign in and allow the request."
  aws sso login --profile "$AWS_PROFILE"
fi
ACCOUNT_ID="$(aws organizations list-accounts --query "Accounts[?Name=='portfolio'].Id | [0]" --output text | tr -d '\r')"
if [[ ! "$ACCOUNT_ID" =~ ^[0-9]{12}$ ]]; then
  warn "Stopping: no account is named portfolio."
  exit 1
fi
for key in sso_session sso_start_url sso_region region; do
  value="$(aws configure get "$key" --profile "$AWS_PROFILE" 2>/dev/null | tr -d '\r' || true)"
  if [[ -n "$value" ]]; then
    aws configure set "$key" "$value" --profile "$MEMBER_PROFILE"
  fi
done
aws configure set sso_account_id "$ACCOUNT_ID" --profile "$MEMBER_PROFILE"
aws configure set sso_role_name AdministratorAccess --profile "$MEMBER_PROFILE"
if [[ "$(aws sts get-caller-identity --profile "$MEMBER_PROFILE" --query Account --output text | tr -d '\r')" != "$ACCOUNT_ID" ]]; then
  warn "Stopping: profile $MEMBER_PROFILE didn't reach portfolio."
  exit 1
fi
ROLE_ARN="arn:aws:iam::$ACCOUNT_ID:role/$ROLE_NAME"
say "PASS: signed in to portfolio"
pause

stage "Check AWS's side"
ISSUER="$(aws iam get-outbound-web-identity-federation-info --profile "$MEMBER_PROFILE" \
  --query IssuerIdentifier --output text 2>/dev/null | tr -d '\r' || true)"
if [[ "$ISSUER" =~ ^https://[a-z0-9-]+\.tokens\.sts\.global\.api\.aws$ ]]; then
  say "PASS: the account's token issuer is on"
else
  warn "This AWS CLI couldn't read the issuer, or it's off."
  step "In the AWS console for portfolio, open IAM, then Account settings."
  step "If Outbound web identity federation is off, stop: the accounts stack isn't applied."
  step "Otherwise copy the Get Token Issuer URL field."
  ask_id ISSUER "Issuer URL:" '^https://[a-z0-9-]+\.tokens\.sts\.global\.api\.aws$'
fi
note "Next, a test token from Singapore. Only its length is printed, never the token."
if TOKEN_LENGTH="$(aws sts get-web-identity-token --region "$REGION" --audience "$AUDIENCE" \
  --signing-algorithm RS256 --duration-seconds 300 --profile "$MEMBER_PROFILE" \
  --query 'length(WebIdentityToken)' --output text 2>/dev/null | tr -d '\r')" \
  && [[ "$TOKEN_LENGTH" =~ ^[0-9]+$ ]]; then
  say "PASS: STS in $REGION issues Anthropic tokens ($TOKEN_LENGTH characters)"
else
  TOKEN_LENGTH=""
  warn "STS in $REGION didn't issue a token. This CLI may be too old to know the call."
  note "Carry on. The Lambda's first call is the real test, and Claude has a fallback."
fi
pause

stage "Billing safety"
open_url "$CONSOLE/settings/billing"
step "On the Billing page, check that auto-reload is off."
note "A leaked credential with auto-reload on charges the card again and again."
step "Note the organization's monthly spend limit. A workspace limit must be lower."
pause "Press Enter when auto-reload is off"

stage "Create the $EPISODE workspace"
open_url "$CONSOLE/settings/workspaces"
step "On the Workspaces page, create a workspace named $EPISODE."
note "The default workspace can't have a spend limit, so the site needs its own."
step "Open the new workspace and copy its ID, which starts wrkspc_."
note "It's on the workspace's page, or in the address bar."
ask_id WORKSPACE_ID "Workspace ID:" '^wrkspc_[A-Za-z0-9]+$'
pause

stage "Workspace limits"
step "In the $EPISODE workspace, open its limits."
step "Set the monthly spend limit to \$30, which is about 30 days at the app's \$1/day cap."
step "Turn on the email alert for that limit, if there is one."
step "If it has rate limits, set the lowest offered for each model group."
note "The app's own per-visitor limit and daily cap come first. These are the backstop."
pause "Press Enter when the limit is set"

stage "Connect workload"
open_url "$CONSOLE/settings/workload-identity-federation"
step "Click Connect workload, then the AWS tile."
say ""
say "Issuer, with discovery mode for the keys:"
printf '    %s\n' "$ISSUER"
say "Service account name:  v1be-$EPISODE"
say "Rule name:             $EPISODE-production"
say "Subject, exact, with no * at the end:"
printf '    %s\n' "$ROLE_ARN"
say "Audience:              $AUDIENCE"
say "Workspace:             $EPISODE"
say "Scope and lifetime:    keep the defaults, workspace:developer and 600 seconds"
say ""
warn "Skip the wizard's live test. The Lambda doesn't exist until the first production deploy."
step "When it's done, copy the service account ID (svac_...) and the rule ID (fdrl_...)."
ask_id SERVICE_ACCOUNT_ID "Service account ID:" '^svac_[A-Za-z0-9]+$'
ask_id FEDERATION_RULE_ID "Federation rule ID:" '^fdrl_[A-Za-z0-9]+$'
pause

stage "Organization ID"
open_url "$CONSOLE/settings/organization"
step "On the Organization page, copy the organization ID. It's a UUID."
ask_id ORGANIZATION_ID "Organization ID:" '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
pause

stage "Save the IDs to SSM"
JSON="{\"organization_id\":\"$ORGANIZATION_ID\",\"workspace_id\":\"$WORKSPACE_ID\",\"service_account_id\":\"$SERVICE_ACCOUNT_ID\",\"federation_rule_id\":\"$FEDERATION_RULE_ID\"}"
say "This writes one plain String parameter in portfolio:"
printf '    %s\n' "$PARAM"
printf '    %s\n' "$JSON"
note "Your session can write it but not read it back, by design (ADR-0009)."
if ! confirm "Write it?"; then
  warn "Stopping. Nothing was written. Run this wizard again when ready."
  exit 1
fi
aws ssm put-parameter --region "$REGION" --profile "$MEMBER_PROFILE" \
  --name "$PARAM" --type String --overwrite --value "$JSON" >/dev/null
VERSION="$(aws ssm describe-parameters --region "$REGION" --profile "$MEMBER_PROFILE" \
  --parameter-filters "Key=Name,Values=$PARAM" --query 'Parameters[0].Version' --output text | tr -d '\r')"
if [[ ! "$VERSION" =~ ^[0-9]+$ ]]; then
  warn "FAIL: SSM doesn't list $PARAM. Tell Claude the error, without any IDs."
  exit 1
fi
say "PASS: $PARAM is saved, version $VERSION"
unset JSON
pause

stage "Done"
say "Workspace, limit and federation rule are set, and the IDs are in SSM."
if [[ -n "$TOKEN_LENGTH" ]]; then
  say "Singapore token test: PASS"
else
  say "Singapore token test: didn't run, or failed"
fi
note "The Lambda's first call proves the rest. If it gets a 401, the Console's"
note "authentication history, on the Workload identity page, says why."
pause

finish
say "Tell Claude: the Singapore test result and the SSM version. No IDs."
}

run_wizard "$@"; exit
